g/W4400104922", "doi": "https://doi.org/10.3929/ethz-b-000719974", "title": "Preference Elicitation for Offline Reinforcement Learning", "publication_year": 2024, "type": "preprint", "cited_by_count": 0, "open_access": {"is_oa": true, "oa_status": "green", "oa_url": "https://arxiv.org/pdf/2406.18450", "any_repository_has_fulltext": true}, "primary_location": {"id": "pmh:oai:arXiv.org:2406.18450", "doi": null, "is_oa": true, "landing_page_url": "http://arxiv.org/abs/2406.18450", "pdf_url": "https://arxiv.org/pdf/2406.18450", "source": {"id": "https://openalex.org/S4306400194", "display_name": "arXiv (Cornell University)", "issn_l": "2331-8422", "issn": ["2331-8422"], "is_oa": true, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": "https://openalex.org/I205783295", "host_organization_name": "Cornell University", "host_organization_lineage": ["https://openalex.org/I205783295"], "host_organization_lineage_names": [], "type": "repository"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "submittedVersion", "is_accepted": false, "is_published": false, "raw_source_name": null, "raw_type": "text"}, "abstract": "Applying reinforcement learning (RL) to real-world problems is often made challenging by the inability to interact with the environment and the difficulty of designing reward functions. Offline RL addresses the first challenge by considering access to an offline dataset of environment interactions labeled by the reward function. In contrast, Preference-based RL does not assume access to the reward function and learns it from preferences, but typically requires an online interaction with the environment. We bridge the gap between these frameworks by exploring efficient methods for acquiring preference feedback in a fully offline setup. We propose Sim-OPRL, an offline preference-based reinforcement learning algorithm, which leverages a learned environment model to elicit preference feedback on simulated rollouts. Drawing on insights from both the offline RL and the preference-based RL literature, our algorithm employs a pessimistic approach for out-of-distribution data, and an optimistic approach for acquiring informative preferences about the optimal policy. We provide theoretical guarantees regarding the sample complexity of our approach, dependent on how well the offline data covers the optimal policy. Finally, we demonstrate the empirical performance of Sim-OPRL in different environments."}]", "excerpt_truncated": true, "source_sha256": "4357002d1ce0464c63ab5d36c3ca6d6924bd41ff89c1b7e75baf63cc159dad62", "verification_required": true, "topic_domain": "emergent_preferences", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1145/3477600", "doi:10.3929/ethz-b-000719974", "openalex:W3216656735", "arxiv:1908.08796", "arxiv:2406.18450"], "source_candidates": ["https://doi.org/10.1145/3477600", "https://arxiv.org/pdf/1908.08796", "https://doi.org/10.3929/ethz-b-000719974", "https://arxiv.org/pdf/2406.18450"], "source_candidate_identities": {}}
